css:
.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.tile {
  display: grid;
  place-items: center;
  height: 56px;
  border: 3px solid transparent;
  border-radius: 8px;
  background-color: #f4f4f5;
  font-weight: 600;
}

/* the first three */
.tile:nth-child(-n + 3) {
  background-color: #fdba74;
}

/* every third */
.tile:nth-child(3n) {
  border-color: #18181b;
}

/* the fourth onwards, but only even ones */
.tile:nth-child(n + 4):nth-child(even) {
  color: #c2410c;
}

/* the last two */
.tile:nth-last-child(-n + 2) {
  background-color: #18181b;
  color: #ffffff;
}
